-- Auto-generated by capex.db.dump — do not edit by hand.
-- Regenerated on every successful DB mutation.
-- Source of truth: data/db/capex.db

BEGIN TRANSACTION;
CREATE TABLE audit_log (
    id           INTEGER PRIMARY KEY AUTOINCREMENT,
    ts           TEXT NOT NULL,
    actor        TEXT NOT NULL,         -- skill name + version, e.g. "sync-companies@0.0.1"
    action       TEXT NOT NULL,         -- e.g. "companies_upsert"
    target_table TEXT NOT NULL,
    target_id    INTEGER,
    payload      TEXT                   -- JSON of what changed
);
CREATE TABLE audit_review_feedback (
    id                    INTEGER PRIMARY KEY AUTOINCREMENT,
    audit_run_id          TEXT NOT NULL,
    cell_key              TEXT NOT NULL,        -- {ticker}:{metric}:{fy}{pt}
    human_input           TEXT NOT NULL,         -- verbatim reviewer text
    formalized_note_id    TEXT,                  -- FK (soft) to human_notes.yaml id
    formalization_json    TEXT,                  -- raw JSON returned by sub-agent
    reviewer              TEXT,                  -- free-text attribution
    reviewed_at           TEXT NOT NULL,
    UNIQUE(audit_run_id, cell_key)
);
CREATE TABLE audit_verdicts (
    id                       INTEGER PRIMARY KEY AUTOINCREMENT,
    extraction_id            INTEGER NOT NULL REFERENCES extractions(id),
    run_id                   TEXT NOT NULL,
    checked_at               TEXT NOT NULL,
    mechanical_flags_json    TEXT NOT NULL,
    llm_verdict              TEXT,
    llm_response_json        TEXT,
    applied_fix_json         TEXT,
    severity                 TEXT NOT NULL CHECK(severity IN ('info', 'warn', 'error'))
);
CREATE TABLE companies (
    ticker                TEXT PRIMARY KEY,
    name                  TEXT NOT NULL,
    preferred_source      TEXT NOT NULL CHECK(preferred_source IN ('sec_edgar', 'hkex')),
    edgar_cik             TEXT,
    hkex_stock_code       TEXT,
    fiscal_year_end_month INTEGER NOT NULL CHECK(fiscal_year_end_month BETWEEN 1 AND 12),
    synced_at             TEXT NOT NULL
, reporting_currency TEXT NOT NULL DEFAULT 'USD');
CREATE TABLE company_quarterly_convention (
    ticker             TEXT PRIMARY KEY REFERENCES companies(ticker),
    default_convention TEXT NOT NULL CHECK(default_convention IN (
        'ytd_cumulative',       -- values are year-to-date (3M/6M/9M/12M)
        'standalone_quarterly', -- values are 3-month standalone as reported
        'three_month_column',   -- filing exposes an explicit 3M column; prefer it
        'semi_annual',          -- HKEX IR pattern (H1 only)
        'unknown'               -- flag for manual review
    )),
    per_metric_json    TEXT,    -- JSON object: {"capital_expenditures": "ytd_cumulative"}
    header_signatures_json TEXT,-- JSON: {"expect_any_of": [...], "must_not_match": [...]}
    synced_at          TEXT NOT NULL
);
CREATE TABLE extraction_evidence (
    id              INTEGER PRIMARY KEY AUTOINCREMENT,
    extraction_id   INTEGER NOT NULL REFERENCES extractions(id),
    excerpt_text    TEXT NOT NULL,
    excerpt_location TEXT,
    excerpt_role    TEXT NOT NULL
        CHECK(excerpt_role IN ('primary_value', 'supporting', 'derivation_input', 'footnote')),
    created_at      TEXT NOT NULL
);
