CREATE TABLE "extractions" (
    id                   INTEGER PRIMARY KEY AUTOINCREMENT,
    source_document_id   INTEGER NOT NULL REFERENCES source_documents(id),
    metric_key           TEXT NOT NULL REFERENCES metric_definitions(key),
    period_type          TEXT NOT NULL DEFAULT '' CHECK(period_type IN (
        '', 'Q1', 'Q2', 'Q3', 'Q4',
        'H1', 'H2', '9M', 'FY', '3M_reported'
    )),
    basis_period_months  INTEGER,
    reporting_convention TEXT,
    value                REAL,
    value_text           TEXT,
    unit                 TEXT NOT NULL,
    quote                TEXT NOT NULL,
    locator_page         INTEGER,
    locator_section      TEXT,
    extraction_type      TEXT NOT NULL CHECK(extraction_type IN ('direct', 'inferred', 'derived')),
    confidence           REAL,
    extracting_model     TEXT NOT NULL,
    protocol_version     TEXT NOT NULL,
    extracted_at         TEXT NOT NULL,
    value_usd            REAL,
    fx_rate              REAL,
    fx_rate_date         TEXT,
    reporting_currency   TEXT NOT NULL DEFAULT 'USD',
    UNIQUE(source_document_id, metric_key, extracting_model, period_type)
);
CREATE TABLE fiscal_calendar (
    id                  INTEGER PRIMARY KEY AUTOINCREMENT,
    ticker              TEXT NOT NULL REFERENCES companies(ticker),
    report_date         TEXT NOT NULL,     -- announced earnings date (YYYY-MM-DD)
    fiscal_date_ending  TEXT NOT NULL,     -- quarter/year-end date (YYYY-MM-DD)
    form_type           TEXT,              -- expected form: 10-Q, 10-K, 20-F, 6-K
    status              TEXT NOT NULL DEFAULT 'upcoming'
        CHECK(status IN ('upcoming', 'detected', 'fetched', 'extracted', 'failed')),
    source              TEXT NOT NULL DEFAULT 'alpha_vantage',
    updated_at          TEXT NOT NULL,
    UNIQUE(ticker, fiscal_date_ending)
);
CREATE TABLE fx_rates (
    currency_pair  TEXT NOT NULL,   -- e.g. 'CNY/USD' (1 CNY = ? USD)
    rate_date      TEXT NOT NULL,   -- ISO date (period-end date)
    rate           REAL NOT NULL,   -- the exchange rate
    source         TEXT NOT NULL DEFAULT 'frankfurter',  -- 'frankfurter' / 'ecb' / 'manual'
    fetched_at     TEXT NOT NULL,
    PRIMARY KEY (currency_pair, rate_date)
);
CREATE TABLE golden_facts (
    id                INTEGER PRIMARY KEY AUTOINCREMENT,
    ticker            TEXT NOT NULL,
    period            TEXT NOT NULL,
    metric_key        TEXT NOT NULL,
    expected_value    REAL,
    expected_unit     TEXT NOT NULL,
    source_doc_sha256 TEXT NOT NULL,
    note              TEXT,
    UNIQUE(ticker, period, metric_key)
);
CREATE TABLE metric_definitions (
    key          TEXT PRIMARY KEY,
    label        TEXT NOT NULL,
    aliases      TEXT NOT NULL,        -- JSON array
    unit_default TEXT NOT NULL,
    description  TEXT
);
CREATE TABLE schema_version (
                version    INTEGER PRIMARY KEY,
                applied_at TEXT NOT NULL
            );
CREATE TABLE "source_documents" (
    id                INTEGER PRIMARY KEY AUTOINCREMENT,
    ticker            TEXT NOT NULL REFERENCES companies(ticker),
    form_type         TEXT NOT NULL CHECK(form_type IN ('10-K', '10-Q', '20-F', '6-K', 'HK-AR', 'HK-IR')),
    filing_date       TEXT NOT NULL,
    period_of_report  TEXT NOT NULL,
    fiscal_year       INTEGER NOT NULL,
    period_token      TEXT NOT NULL CHECK(period_token IN ('AR', 'Q1', 'Q2', 'Q3', 'Q4', 'H1', 'H2')),
    sha256            TEXT NOT NULL UNIQUE,
    raw_path          TEXT NOT NULL,
    canonical_path    TEXT,
    source            TEXT NOT NULL CHECK(source IN ('sec_edgar', 'hkex', 'xbrl_api')),
    source_url        TEXT NOT NULL,
    accession_number  TEXT,
    fetched_at        TEXT NOT NULL,
    fetcher_version   TEXT NOT NULL,
    protocol_version  TEXT NOT NULL,
    UNIQUE(ticker, form_type, period_of_report)
);
CREATE TABLE validation_results (
    id            INTEGER PRIMARY KEY AUTOINCREMENT,
    extraction_id INTEGER NOT NULL REFERENCES extractions(id),
    check_name    TEXT NOT NULL,       -- 'provenance_substring' | 'range_check' | etc
    passed        INTEGER NOT NULL CHECK(passed IN (0, 1)),
    details       TEXT,                 -- JSON
    checked_at    TEXT NOT NULL
);
CREATE INDEX idx_validation_results_extraction
    ON validation_results(extraction_id);
CREATE INDEX idx_audit_log_ts
    ON audit_log(ts);
CREATE INDEX idx_evidence_extraction ON extraction_evidence(extraction_id);
CREATE INDEX idx_fiscal_calendar_date ON fiscal_calendar(report_date);
CREATE INDEX idx_fiscal_calendar_status ON fiscal_calendar(status);
CREATE INDEX idx_extractions_metric ON extractions(metric_key);
CREATE INDEX idx_extractions_doc_metric_period
    ON extractions(source_document_id, metric_key, period_type);
CREATE INDEX idx_source_documents_ticker_period
    ON source_documents(ticker, period_of_report);
CREATE INDEX idx_audit_verdicts_ext
    ON audit_verdicts(extraction_id);
CREATE INDEX idx_audit_verdicts_run
    ON audit_verdicts(run_id);
CREATE INDEX idx_arf_run ON audit_review_feedback(audit_run_id);
CREATE INDEX idx_arf_note ON audit_review_feedback(formalized_note_id);
DELETE FROM "sqlite_sequence";
COMMIT;
